__global__ void cumsum_mul_kernel(const float* a, const bool* m, float* out, int batch_size, int n_cols) {
    int b = blockIdx.x;
    if (b >= batch_size) return;
    extern __shared__ float sdata[];
    // Not using shared memory; just compute per-thread sum of columns starting at threadIdx.x.
    int col_start = threadIdx.x;
    float sum = 0.0f;
    for (int i = col_start; i < n_cols; ++i) {
        if (m[b * n_cols + i]) { // but m is bool, need to cast
            sum += a[b * n_cols + i];
        }
    }
    out[b * n_cols + col_start] = sum;
}
